using System.Buffers;
using System.Text;
using Microsoft.Win32.SafeHandles;

namespace Pillion.Indexing.Discovery;

/// <summary>
/// The exclusions that need the file's first bytes: a NUL byte in the first 8 KB means binary, and an auto-generated
/// header in the first 2 KB means generated code. A file with a UTF-16 byte order mark is text, although it is full of
/// NUL bytes.
/// </summary>
/// <remarks>
/// A generated-file marker counts only where generators write it (issue #96, work item 3.2): at the start of a comment
/// line within the first <see cref="HeaderProbeLines"/> lines of the first 2 KB, after the comment leader (<c>//</c>,
/// <c>///</c>, <c>/*</c>, <c>*</c>, <c>'</c>, <c>#</c>, <c>--</c>, <c>;</c>, <c>%</c>, <c>&lt;!--</c>, <c>rem</c>) and any
/// decoration (<c>-</c>, <c>=</c>, <c>*</c>, <c>#</c>). A file that merely mentions a marker in its text (a string literal,
/// a sentence in a comment) is source.
/// </remarks>
public static class ContentInspector
{
    /// <summary>How many leading bytes are searched for a NUL byte.</summary>
    public const int BinaryProbeBytes = 8 * 1024;

    /// <summary>How many leading bytes are searched for an auto-generated header.</summary>
    public const int HeaderProbeBytes = 2 * 1024;

    /// <summary>How many leading lines (within the first 2 KB) a generated-file marker may be on; a licence header fits above it.</summary>
    public const int HeaderProbeLines = 50;

    private static readonly string[] GeneratedMarkers = ["<auto-generated", "<autogenerated", "@generated", "generated by the protocol buffer compiler"];

    private static readonly string[] CommentLeaders = ["<!--", "///", "//", "/*", "**", "*", "'", "#", "--", ";", "%"];

    /// <summary>Reads the start of a file and decides whether it is binary or generated.</summary>
    /// <param name="fullPath">The file to read; it is opened with sharing so a file open in an editor can be read.</param>
    /// <returns>The decision: <see cref="ExclusionReason.None"/> for a text file to index, <see cref="ExclusionReason.Binary"/>, <see cref="ExclusionReason.GeneratedHeader"/>, or <see cref="ExclusionReason.Unreadable"/> when the file cannot be read.</returns>
    public static FileDecision Inspect(string fullPath)
    {
        ArgumentNullException.ThrowIfNull(fullPath);

        var buffer = ArrayPool<byte>.Shared.Rent(BinaryProbeBytes);
        try
        {
            int read;
            try
            {
                using SafeFileHandle handle = File.OpenHandle(fullPath, FileMode.Open, FileAccess.Read, FileShare.ReadWrite | FileShare.Delete, FileOptions.SequentialScan);
                read = ReadFully(handle, buffer.AsSpan(0, BinaryProbeBytes));
            }
            catch (Exception ex) when (ex is IOException or UnauthorizedAccessException)
            {
                return new FileDecision(ExclusionReason.Unreadable, ex.Message);
            }

            return Inspect(buffer.AsSpan(0, read));
        }
        finally
        {
            ArrayPool<byte>.Shared.Return(buffer);
        }
    }

    /// <summary>Decides from the first bytes of a file (up to <see cref="BinaryProbeBytes"/>) whether it is binary or generated.</summary>
    /// <param name="head">The first bytes of the file.</param>
    /// <returns>The decision; see <see cref="Inspect(string)"/>.</returns>
    public static FileDecision Inspect(ReadOnlySpan<byte> head)
    {
        var utf16 = head.Length >= 2 && ((head[0] == 0xFF && head[1] == 0xFE && !(head.Length >= 4 && head[2] == 0 && head[3] == 0)) || (head[0] == 0xFE && head[1] == 0xFF));
        if (!utf16 && head.Contains((byte)0))
        {
            return new FileDecision(ExclusionReason.Binary);
        }

        var header = head[..Math.Min(head.Length, HeaderProbeBytes)];
        Span<char> text = stackalloc char[HeaderProbeBytes];
        int length;
        if (utf16)
        {
            var encoding = header[0] == 0xFF ? Encoding.Unicode : Encoding.BigEndianUnicode;
            length = encoding.GetChars(header[..(header.Length & ~1)], text);
        }
        else
        {
            // Latin-1 keeps one char per byte, which is all the ASCII markers need.
            length = Encoding.Latin1.GetChars(header, text);
        }

        return FindGeneratedMarker(text[..length]) is { } marker
            ? new FileDecision(ExclusionReason.GeneratedHeader, marker)
            : FileDecision.Included;
    }

    /// <summary>
    /// Finds a generated-file marker at the start of a comment line within the first <see cref="HeaderProbeLines"/> lines
    /// (issue #96): the marker must follow the line's comment leader and decoration, not merely appear somewhere in the text.
    /// </summary>
    /// <param name="chars">The decoded head of the file.</param>
    /// <returns>The marker found, or <see langword="null"/>.</returns>
    internal static string? FindGeneratedMarker(ReadOnlySpan<char> chars)
    {
        // A byte order mark precedes the first comment leader: U+FEFF after a UTF-16 decode, or the three Latin-1 characters
        // of the UTF-8 mark (EF BB BF) after the one-char-per-byte decode.
        if (chars.StartsWith("﻿", StringComparison.Ordinal))
        {
            chars = chars[1..];
        }
        else if (chars.StartsWith("ï»¿", StringComparison.Ordinal))
        {
            chars = chars[3..];
        }

        var lines = 0;
        while (chars.Length > 0 && lines < HeaderProbeLines)
        {
            var end = chars.IndexOfAny('\r', '\n');
            var line = end < 0 ? chars : chars[..end];
            if (end < 0)
            {
                chars = [];
            }
            else
            {
                var next = end + 1;
                if (chars[end] == '\r' && next < chars.Length && chars[next] == '\n')
                {
                    next++;
                }

                chars = chars[next..];
            }

            lines++;
            var comment = CommentBody(line);
            if (comment.Length == 0)
            {
                continue;
            }

            foreach (var marker in GeneratedMarkers)
            {
                if (comment.StartsWith(marker, StringComparison.OrdinalIgnoreCase))
                {
                    return marker;
                }
            }

            // Go's convention: "// Code generated by ... DO NOT EDIT."
            if (comment.StartsWith("code generated", StringComparison.OrdinalIgnoreCase) && comment.Contains("do not edit", StringComparison.OrdinalIgnoreCase))
            {
                return "Code generated ... DO NOT EDIT";
            }
        }

        return null;
    }

    /// <summary>
    /// The text of a comment line after its leader and decoration, trimmed; empty when the line is not a comment (code, a
    /// blank line, or markup other than a comment opener).
    /// </summary>
    private static ReadOnlySpan<char> CommentBody(ReadOnlySpan<char> line)
    {
        var rest = line.TrimStart();
        var found = false;
        foreach (var leader in CommentLeaders)
        {
            if (rest.StartsWith(leader, StringComparison.Ordinal))
            {
                rest = rest[leader.Length..];
                found = true;
                break;
            }
        }

        if (!found)
        {
            // "REM" and "rem" (batch files, BASIC) need a word boundary.
            if (rest.Length > 3 && rest.StartsWith("rem", StringComparison.OrdinalIgnoreCase) && char.IsWhiteSpace(rest[3]))
            {
                rest = rest[3..];
            }
            else
            {
                return [];
            }
        }

        // Decoration such as "//-----", "// ======", "/* ***", "# ###".
        return rest.TrimStart(" \t-=*#".AsSpan());
    }

    private static int ReadFully(SafeFileHandle handle, Span<byte> buffer)
    {
        var total = 0;
        while (total < buffer.Length)
        {
            var read = RandomAccess.Read(handle, buffer[total..], total);
            if (read == 0)
            {
                break;
            }

            total += read;
        }

        return total;
    }
}
